{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Verapamil, a close dimethoxyphenyl tertiary-amine analogue, has 34% absolute oral bioavailability in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Praziquantel, an amide-containing heterocycle, showed 27.2% oral bioavailability in patients, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Noscapine, a dimethoxy-substituted isoquinoline alkaloid, has 30% absolute oral bioavailability in healthy volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C67"],
      "claim": "Sulpiride, a basic benzamide, has 35% oral bioavailability in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Encainide, a dimethoxyphenyl amide with a basic amine, has 32 ± 7% oral bioavailability in normal subjects, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C61"],
      "claim": "Alfentanil, a basic amide opioid, has about 42% absolute oral bioavailability in volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Levosulpiride, a close sulpiride analogue, has 23.4% absolute oral bioavailability in Chinese volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Valbenazine, a dimethoxytetrahydroisoquinoline with a basic amine, has about 49% absolute oral bioavailability in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Colchicine has a mean absolute oral bioavailability of 55% in elderly subjects, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Codeine, a basic alkaloid, has oral bioavailability of 42–71% in healthy volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C71"],
      "claim": "Verapamil in one study had 19.4% oral bioavailability, just below the 20% threshold, indicating borderline risk.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All high-transfer analogues show absolute oral bioavailability mostly in the 23–55% range, with only a few borderline sub-20% values; the weight of evidence supports F >= 20% for the query.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "The query has a low neutral fraction (0.02) due to a basic pKa of 9.05, which may limit passive absorption; no experimental permeability data are available.",
    "Several analogue F values are borderline (20–30%), and some individual measurements fall below 20%.",
    "No data on first-pass metabolism, transporter effects, or formulation effects for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

